jsonb_build_array(jsonb_build_object('title','Guia de investigação geográfica — '||code,'purpose',goal,'sections',jsonb_build_array(
 jsonb_build_object('heading','Prepare o cenário protegido','content',jsonb_build_array('Use município, bairro, moradia, trajeto, rotina e história familiar fictícios; nunca peça endereço, geolocalização, fotografia da moradia, caminho real, horário ou história migratória pessoal da criança.','Apresente moradias, culturas, famílias, trabalhos e modos de deslocamento diversos sem classificar um como superior.')),
 jsonb_build_object('heading','Modele o raciocínio geográfico','content',jsonb_build_array('Ensine a observar pistas, localizar, comparar, relacionar e justificar com imagem, mapa, maquete, sequência temporal ou objetos.','Diferencie fato observado de hipótese e mostre relações entre pessoas, lugares, natureza, trabalho, transporte e comunicação.','Referenciais espaciais devem admitir diferentes lateralidades, percepções visuais, mobilidades e formas de orientação.')),
 jsonb_build_object('heading','Rotina adaptativa','content',jsonb_build_array('Dê uma instrução por vez, reduza estímulos concorrentes, modele um exemplo e use pistas graduadas.','Aceite fala, apontamento, cartões, objetos, maquete, desenho, áudio, digitação, escrita ou tecnologia assistiva.','Não avalie memória, leitura, visão, fala ou coordenação motora como se fossem compreensão geográfica.')),
 jsonb_build_object('heading','Critério','content','Resolve quatro de cinco situações usando ao menos uma pista espacial, temporal, ambiental ou social coerente.')))),
jsonb_build_array(jsonb_build_object('title','1. Observar e identificar','instruction','Observe imagem, objeto, mapa ou maquete fictícia e identifique pistas relevantes.','activity','Separe o que pode ser observado do que ainda precisa ser investigado.','support','Vocabulário visual, exploração tátil opcional e exemplo resolvido.'),jsonb_build_object('title','2. Localizar, ordenar ou comparar','instruction','Use posição, visão, sequência temporal, mudança, permanência ou conexão entre lugares.','activity','Organize cartões, símbolos, objetos ou trechos de mapa relacionados a '||lower(title)||'.','support','Prática guiada antes da independente e pistas graduadas.'),jsonb_build_object('title','3. Relacionar e explicar','instruction','Explique a relação entre pessoas, natureza, trabalho, circulação e usos do espaço.','activity','Apresente uma conclusão e a pista que a sustenta.','support','Resposta oral, apontada, tátil, desenhada, gravada, digitada, escrita ou assistida.')),
jsonb_build_array(jsonb_build_object('page',1,'answer','Identifica elementos e uma pista observável.'),jsonb_build_object('page',2,'answer','Localiza, ordena ou compara com referência coerente.'),jsonb_build_object('page',3,'answer','Explica uma relação apoiada em evidência.','teacher_note','Registre autonomia, apoio eficaz e próximo passo; não registre localização, rota, rotina ou história familiar real.')),
jsonb_build_object('response_modes',jsonb_build_array('oral','pointing','cards','objects','model','drawing','audio','typing','writing','assistive_technology'),'routine','adjustable','one_instruction_at_a_time',true,'read_aloud',true,'large_text',true,'visual_schedule',true,'planned_pause',true,'low_distraction',true,'age_respectful',true,'privacy_preserving',true,'fictional_location_only',true,'no_live_geolocation',true,'no_personal_migration_disclosure',true,'housing_dignity',true,'cultural_respect',true,'anti_stereotype',true,'mobility_vision_inclusive',true,'print','grayscale-safe'),true,true,true,'published','/escola-brilha/curso/geografia-2ano/'||code FROM lessons
